package com.griffin.prismprobe;
import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.os.*;import java.io.*;import java.nio.*;import java.util.*;
public final class CaptureService extends Service {
 static final int W=480,H=270;HandlerThread worker;Handler handler;MediaProjection projection;VirtualDisplay display;ImageReader reader;String label;long last,until;int frames;int[] previous;File folder;
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent intent,int flags,int id){if(intent==null)return START_NOT_STICKY;String action=intent.getAction();if("STOP".equals(action)){stopSelf();return START_NOT_STICKY;}if("SAMPLE".equals(action)){final String value=intent.getStringExtra("label");if(handler!=null&&value!=null&&value.matches("[a-z0-9_-]{1,32}"))handler.post(()->{label=value;frames=0;previous=null;last=0;until=SystemClock.elapsedRealtime()+10000;});return START_NOT_STICKY;}
 if(!"START".equals(action)||projection!=null)return START_NOT_STICKY;
 NotificationManager manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("probe","Temporary capture test",NotificationManager.IMPORTANCE_LOW));startForeground(1,new Notification.Builder(this,"probe").setContentTitle("Prism capture test").setContentText("No audio or network; stops automatically after five minutes").setSmallIcon(android.R.drawable.ic_menu_camera).build());
 folder=getFilesDir();worker=new HandlerThread("bounded-capture");worker.start();handler=new Handler(worker.getLooper());
 try{projection=((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).getMediaProjection(intent.getIntExtra("result",-1),intent.getParcelableExtra("data"));projection.registerCallback(new MediaProjection.Callback(){public void onStop(){stopSelf();}},handler);reader=ImageReader.newInstance(W,H,PixelFormat.RGBA_8888,2);reader.setOnImageAvailableListener(r->{try(Image image=r.acquireLatestImage()){long now=SystemClock.elapsedRealtime();if(image==null||label==null||now>until||now-last<450)return;last=now;Image.Plane plane=image.getPlanes()[0];ByteBuffer buffer=plane.getBuffer();Bitmap padded=Bitmap.createBitmap(plane.getRowStride()/plane.getPixelStride(),H,Bitmap.Config.ARGB_8888);padded.copyPixelsFromBuffer(buffer);Bitmap bitmap=Bitmap.createBitmap(padded,0,0,W,H);int[] pixels=new int[W*H];bitmap.getPixels(pixels,0,W,0,0,W,H);long sum=0,delta=0;int black=0,count=0;for(int y=H/4;y<H*3/4;y+=2)for(int x=W/4;x<W*3/4;x+=2){int p=pixels[y*W+x],r0=(p>>16)&255,g=(p>>8)&255,b=p&255;sum+=r0+g+b;if(Math.max(r0,Math.max(g,b))<8)black++;if(previous!=null){int q=previous[y*W+x];delta+=Math.abs(r0-((q>>16)&255))+Math.abs(g-((q>>8)&255))+Math.abs(b-(q&255));}count++;}try(FileWriter out=new FileWriter(new File(folder,label+".csv"),true)){out.write(String.format(Locale.US,"%d,%d,%.4f,%.4f,%.4f%n",now,frames,sum/(3.0*count),black/(double)count,previous==null?-1:delta/(3.0*count)));}if(frames==0||now>=until-900){try(FileOutputStream out=new FileOutputStream(new File(folder,label+(frames==0?"-first":"-last")+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}}previous=pixels;frames++;if(bitmap!=padded)bitmap.recycle();padded.recycle();}catch(Exception e){android.util.Log.e("PrismCaptureProbe","sample error: "+e.getClass().getSimpleName());}},handler);display=projection.createVirtualDisplay("Prism bounded capture",W,H,160,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,handler);handler.postDelayed(()->stopSelf(),300000);}catch(Exception e){android.util.Log.e("PrismCaptureProbe","start error: "+e.getClass().getSimpleName());stopSelf();}return START_NOT_STICKY;}
 public void onDestroy(){if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null){MediaProjection p=projection;projection=null;p.stop();}if(worker!=null)worker.quitSafely();stopForeground(true);super.onDestroy();}
}
